-- 第 1 步：只建科目和章节（先只跑这一份）
on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  subject_id = excluded.subject_id,
  title = excluded.title,
  sort_order = excluded.sort_order;

-- 跑完应看到 subjects=3, chapters=18
select
  (select count(*) from public.subjects) as subjects,
  (select count(*) from public.chapters where user_id is null) as chapters;
